 46	public class FnNameInfo {
 47	    final List<StaticParam> static_params;
 48	    private final List<StaticParam> trait_static_params;
 49	    private final Type returnType;
 50	    private final Type paramType;
 51	    final APIName ifNone;
 52	    private final IdOrOp name;
 53	    final Span span;
 54	    
 55	    public FnNameInfo(List<StaticParam> static_params,
 56	            List<StaticParam> trait_static_params, Type returnType,
 57	            Type paramType, APIName ifNone, IdOrOp name, Span span) {
 58	        
 59	        super();
 60	        this.static_params = static_params;
 61	        this.trait_static_params = trait_static_params;
 62	        this.returnType = returnType;
 63	        this.paramType = paramType;
 64	        this.ifNone = ifNone;
 65	        this.name = name;
 66	        this.span = span;
 67	    }
