 69	    public FnNameInfo convertGenericMethodToClosureDecl(int self_index,
 70	            List<StaticParam> to_static_params) {
 71	        Id sp_name = NodeFactory.makeId(span, Naming.UP_INDEX);
 72	        Id p_name = NamingCzar.selfName(span);
 73	        StaticParam new_sp = NodeFactory.makeTypeParam(span, Naming.UP_INDEX);
 74	        Type inserted_param_type = NodeFactory.makeVarType(span, sp_name);
 75	        // convert paramType to list of types, remove self, add inserted_param_type at zero.
 76	        List<Type> param_types = paramType instanceof TupleType ?
 77	                ((TupleType) paramType).getElements() : Useful.list(paramType);
 78	        if (self_index != Naming.NO_SELF)
 79	            param_types = new DeletedList<Type>(param_types, self_index);
 80	        param_types = new InsertedList<Type>(param_types, 0, inserted_param_type);
 81	        Type new_param_type = param_types.size() == 1 ?
 82	                param_types.get(0) :
 83	                    NodeFactory.makeTupleType(span, param_types);
 84	        // edit static params -- new_sp, method_sp, trait_sp
 85	        List<StaticParam> new_sparams =
 86	            new ConcatenatedList<StaticParam>(
 87	                    new InsertedList<StaticParam>(static_params, 0, new_sp),
 88	                to_static_params);
 89	        // This use of trait_static_params is perhaps a little dubious; we'll see.
 90	        return new FnNameInfo(new_sparams, trait_static_params, returnType, new_param_type,ifNone, getName(), span);
 91	    }
