105	    public FnNameInfo(Functional x, APIName ifNone) {
106	        HasTraitStaticParameters htsp = (HasTraitStaticParameters) x;
107	        trait_static_params =  x instanceof HasTraitStaticParameters ?
108	            ((HasTraitStaticParameters)x).traitStaticParameters():
109	                Collections.<StaticParam>emptyList();
110	        static_params = x.staticParameters();
111	        ArrowType at = fndeclToType(x, Naming.NO_SELF);
112	        returnType = at.getRange();
