119	    /**
120	     * Returns the ArrowType of a method where the self parameter (if any)
121	     * has been removed from the domain.  This is used to create signatures
122	     * for the method part of a functional method.
123	     * 
124	     * @param x
125	     * @param selfIndex
126	     * @return
127	     */
128	    static ArrowType fndeclToType(Functional x, int selfIndex) {
129	        Type rt = x.getReturnType().unwrap();
130	        List<Param> lp = x.parameters();
131	        if (selfIndex != Naming.NO_SELF)
132	            lp = new DeletedList<Param>(lp, selfIndex);
133	        return typeAndParamsToArrow(x.getSpan(), rt, lp);
134	    }
135	
136	    /**
137	     * @param x
138	     * @param rt
139	     * @param lp
140	     * @return
141	     */
142	    static ArrowType typeAndParamsToArrow(Span span, Type rt, List<Param> lp) {
143	        Type dt = null;
144	        switch (lp.size()) {
145	        case 0:
146	            dt = NodeFactory.makeVoidType(span);
147	            break;
148	        case 1:
149	            dt = (Type)lp.get(0).getIdType().unwrap(); // TODO varargs
150	            break;
151	        default:
152	            dt = NodeFactory.makeTupleType(Useful.applyToAll(lp, new Fn<Param,Type>() {
153	                @Override
154	                public Type apply(Param x) {
155	                    return (Type)x.getIdType().unwrap(); // TODO varargs
156	                }}));
157	            break;
158	        }
159	        return NodeFactory.makeArrowType(NodeFactory.makeSpan(dt,rt), dt, rt);
160	    }
161	    
162	    public TypeArg boundsFor(StaticParam sp) {
163	        List<BaseType> tl = sp.getExtendsClause();
164	        if (tl.size() == 0) {
165	            return NodeFactory.makeTypeArg(NodeFactory.makeTraitType(
166	                    NodeFactory.makeId(sp.getInfo().getSpan(),
167	                            Option.<APIName>some(NamingCzar.fortressLibrary()), "Object")));
168	        } else if (tl.size() == 1) {
169	            return NodeFactory.makeTypeArg(tl.get(0));
170	        } else {
171	            return NodeFactory.makeTypeArg(NodeFactory.makeIntersectionType(tl));
172	        }
173	    }
174	    
175	    public ArrowType normalizedSchema(Type at) {
176	        // make list of params by concatenating trait and method params
177	        // make list of synthesized args in form "1t", "2t", ..., "1m", "2m", ..
178	        // use STR to normalize the return type.
179	        List<StaticParam> lsp = new ArrayList<StaticParam>();
180	        List<StaticArg> lsa = new ArrayList<StaticArg>();
181	        int i = 1;
182	        for (StaticParam sp : trait_static_params) {
183	            lsp.add(sp);
184	            lsa.add(boundsFor(sp));
185	            // lsa.add(NodeFactory.makeTypeArg(NodeFactory.makeVarType(sp.getInfo().getSpan(), i + "t")));
186	            i++;
187	        }
188	        i = 1;
189	        for (StaticParam sp : static_params) {
190	            lsp.add(sp);
191	            lsa.add(boundsFor(sp));
192	            // lsa.add(NodeFactory.makeTypeArg(NodeFactory.makeVarType(sp.getInfo().getSpan(), i + "m")));
193	            i++;
194	        }
195	        StaticTypeReplacer str = new StaticTypeReplacer(lsp, lsa);
196	        ArrowType new_at =  (ArrowType) (str.replaceIn(at));
197	        return  new_at;
198	    }
