200	    /**
201	     * Returns the ArrowType of a method where the self parameter (if any)
202	     * has been removed from the domain.  This is used to create signatures
203	     * for the method part of a functional method.
204	     * 
205	     * @param x
206	     * @param selfIndex
207	     * @return
208	     */
209	    static ArrowType methodArrowType(FnNameInfo x, int selfIndex) {
210	        Type rt = x.returnType;
211	        Type dt = x.paramType;
212	        if (selfIndex != Naming.NO_SELF) {
213	            if (dt instanceof TupleType) {
214	                List<Type> types = ((TupleType) dt).getElements();
215	                types = new DeletedList<Type>(types, selfIndex);
216	                dt = types.size() == 1 ?
217	                        types.get(0) :
218	                        NodeFactory.makeTupleType(NodeUtil.getSpan(dt), types);
219	            } else {
220	               dt = NodeFactory.makeVoidType(x.span);
221	            }
222	        }
223	        return NodeFactory.makeArrowType(NodeFactory.makeSpan(dt,rt), dt, rt);
224	    }
225	    
226	    public ArrowType methodArrowType(int selfIndex) {
227	        return normalizedSchema(methodArrowType(this, selfIndex));
228	    }
229	
230	    public ArrowType functionArrowType() {
231	        return methodArrowType(this, Naming.NO_SELF);
232	    }
